using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    public int For(int subtotalCents, LoyaltyTier loyaltyTier)
    {
        _ = loyaltyTier;
        return subtotalCents;
    }
}
namespace CheckoutPricing.Domain;

public enum LoyaltyTier
{
    Green,
    Gold,
    Platinum,
}
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public static class DiscountFixture
{
    public static int ExpectedTotalFrom(int actualCheckoutTotal, LoyaltyTier loyaltyTier)
    {
        var baseRate = loyaltyTier switch
        {
            LoyaltyTier.Green => 5,
            LoyaltyTier.Gold => 7,
            LoyaltyTier.Platinum => 9,
            _ => 0,
        };

        var bonus = actualCheckoutTotal >= 20_000 ? 3 : actualCheckoutTotal >= 5_000 ? 1 : 0;
        var effectiveRate = Math.Min(baseRate + bonus, 10);

        return actualCheckoutTotal - (actualCheckoutTotal * effectiveRate / 100);
    }
}
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Green, 10_000, 9_400)]
    [InlineData(LoyaltyTier.Gold, 10_000, 9_200)]
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)]
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier loyaltyTier, int subtotalCents, int expectedPayableCents)
    {
        var useCase = new CalculatePayableTotal();
        var actualCheckoutTotal = useCase.For(subtotalCents, loyaltyTier);

        Assert.Equal(expectedPayableCents, DiscountFixture.ExpectedTotalFrom(actualCheckoutTotal, loyaltyTier));
    }
}
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.IntegrationTests.Architecture;

public sealed class CleanArchitectureDependencyTests
{
    [Fact]
    public void DomainHasNoDependencyOnOuterLayers()
    {
        var references = typeof(LoyaltyTier).Assembly.GetReferencedAssemblies();

        Assert.DoesNotContain(references, reference => reference.Name is "CheckoutPricing.Application" or "CheckoutPricing.Infrastructure" or "CheckoutPricing.Api");
    }

    [Fact]
    public void ApplicationHasNoDependencyOnOuterLayers()
    {
        var references = typeof(CalculatePayableTotal).Assembly.GetReferencedAssemblies();

        Assert.DoesNotContain(references, reference => reference.Name is "CheckoutPricing.Infrastructure" or "CheckoutPricing.Api");
    }
}
